#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# create-api-manager-instance.sh — Create (or reuse + version-align) the API Manager instance; output API_ID.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/tasks/create-api-manager-instance.yml
#   step   : "Create API Manager Instance" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
#
# Inputs (environment):
#   MDF_ARTIFACT_ID       <- ${{ parameters.artifactId }}  [required]
#   MDF_BEARER_TOKEN      <- ${{ parameters.bearerToken }}  [required]
#   MDF_BG_ID             <- ${{ parameters.bgId }}  [default: $(BG_ID)]
#   MDF_ENV_ID            <- ${{ parameters.envId }}  [default: $(ENV_ID)]
#   MDF_RAML_ARTIFACT_ID  <- ${{ parameters.ramlArtifactId }}  [default: (empty)]
#   MDF_RAML_GROUP_ID     <- ${{ parameters.ramlGroupId }}  [default: (empty)]
#   MDF_RAML_VERSION      <- ${{ parameters.ramlVersion }}  [default: (empty)]
# Outputs: isNewAPIInstance (output), API_ID (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_BEARER_TOKEN?MDF_BEARER_TOKEN is required (Azure parameter bearerToken)}"
: "${MDF_BG_ID=}"
: "${MDF_ENV_ID=}"
: "${MDF_RAML_ARTIFACT_ID=}"
: "${MDF_RAML_GROUP_ID=}"
: "${MDF_RAML_VERSION=}"

# >>> extracted body
BG_ID="${MDF_BG_ID}"
ENV_ID="${MDF_ENV_ID}"

echo "[DEBUG] ============================================"
echo "[DEBUG] CREATE API MANAGER INSTANCE"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   envId=$ENV_ID"
echo "[DEBUG]   artifactId=${MDF_ARTIFACT_ID}"
echo "[DEBUG]   ramlArtifactId=${MDF_RAML_ARTIFACT_ID}"
echo "[DEBUG]   ramlVersion=${MDF_RAML_VERSION}"
echo "[DEBUG]   ramlGroupId=${MDF_RAML_GROUP_ID}"
echo "[DEBUG] ============================================"

# Fetch client management provider for the environment
echo "[DEBUG] Fetching client management providers..."
get_client_response=$(curl -i -s --request GET \
  --url "https://anypoint.mulesoft.com/accounts/api/organizations/${BG_ID}/environments/${ENV_ID}/clientManagementProviders" \
  --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")

GET_CLIENT_STATUS=$(echo "$get_client_response" | head -n 1 | awk '{print $2}')
GET_CLIENT_BODY=$(echo "$get_client_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)
echo "[DEBUG] Client management providers response status: $GET_CLIENT_STATUS"
echo "[DEBUG] Client management providers body: $GET_CLIENT_BODY"

PROVIDER_ID=""
if [[ "$GET_CLIENT_STATUS" == "200" ]]; then
  PROVIDER_ID=$(echo "$GET_CLIENT_BODY" | jq -r '.suggestedClientManagementProviderIds[0] // empty')
  echo "[DEBUG] Resolved PROVIDER_ID: $PROVIDER_ID"
else
  echo "[DEBUG] Failed to fetch client management providers. Status=$GET_CLIENT_STATUS"
  ci_log_error "Failed to fetch client management providers."
  echo "Status: $GET_CLIENT_STATUS"
  exit 1
fi

# Build creation payload
json_payload=$(jq -n \
  --arg ramlAssetId "${MDF_RAML_ARTIFACT_ID}" \
  --arg groupId "$BG_ID" \
  --arg version "${MDF_RAML_VERSION}" \
  --arg label "${MDF_ARTIFACT_ID}" \
  --arg providerId "$PROVIDER_ID" \
  '{
    technology: "mule4",
    endpoint: { muleVersion4OrAbove: true, type: "raml" },
    spec: { assetId: $ramlAssetId, groupId: $groupId, version: $version },
    instanceLabel: $label,
    providerId: (if $providerId == "" then null else $providerId end)
  }')

echo "[DEBUG] API Manager creation payload:"
echo "[DEBUG] $json_payload"
echo "Creating API Manager instance for: ${MDF_ARTIFACT_ID}"

create_response=$(curl -i -s --location \
  "https://anypoint.mulesoft.com/apimanager/xapi/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis" \
  --header "Content-Type: application/json" \
  --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
  --data "$json_payload")

HTTP_STATUS=$(echo "$create_response" | head -n 1 | awk '{print $2}')
BODY=$(echo "$create_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)
echo "[DEBUG] Create API instance response status: $HTTP_STATUS"
echo "[DEBUG] Create API instance response body: $BODY"

if [[ "$HTTP_STATUS" == "201" ]]; then
  api_instance_name=$(echo "$BODY" | jq -r '.autodiscoveryInstanceName')
  api_id=$(echo "$api_instance_name" | cut -d ':' -f 2)
  echo "API Manager instance created: $api_instance_name"
  echo "[DEBUG] New instance — autodiscoveryInstanceName=$api_instance_name, api_id=$api_id"
  ci_set_var isNewAPIInstance "true"

elif [[ "$HTTP_STATUS" == "409" ]]; then
  echo "API Manager instance already exists. Fetching details..."
  echo "[DEBUG] 409 Conflict — instance exists, fetching by instanceLabel=${MDF_ARTIFACT_ID}"

  get_response=$(curl -i -s --request GET \
    --url "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis?instanceLabel=${MDF_ARTIFACT_ID}" \
    --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")

  GET_BODY=$(echo "$get_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)
  echo "[DEBUG] GET existing instance response: $GET_BODY"
  api_instance_name=$(echo "$GET_BODY" | jq -r '.assets[0].apis[0].autodiscoveryInstanceName')
  api_id=$(echo "$api_instance_name" | cut -d ':' -f 2)
  existing_version=$(echo "$GET_BODY" | jq -r '.assets[0].apis[0].assetVersion')
  echo "[DEBUG] Existing instance: autodiscoveryInstanceName=$api_instance_name, api_id=$api_id, assetVersion=$existing_version"

  # Update version if it differs
  if [[ "$existing_version" != "${MDF_RAML_VERSION}" ]]; then
    echo "Updating API instance version from $existing_version to ${MDF_RAML_VERSION}..."
    echo "[DEBUG] PATCH to update assetVersion from $existing_version to ${MDF_RAML_VERSION}"
    curl -sS -X PATCH \
      --url "https://anypoint.mulesoft.com/apimanager/xapi/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/$api_id" \
      --header "Content-Type: application/json" \
      --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
      --data "{\"assetVersion\": \"${MDF_RAML_VERSION}\"}" > /dev/null
    echo "Version updated."
  else
    echo "[DEBUG] Version matches ($existing_version) — no update needed"
  fi

  ci_set_var isNewAPIInstance "false"

else
  echo "[DEBUG] Unexpected status code: $HTTP_STATUS"
  ci_log_error "API Manager instance creation failed."
  echo "Status: $HTTP_STATUS"
  echo "Response: $BODY"
  exit 1
fi

ci_set_var API_ID "$api_id"
echo "API ID: $api_id"
echo "[DEBUG] CREATE API MANAGER INSTANCE COMPLETE — API_ID=$api_id"
# <<< extracted body
